using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change #1: Discriminator property renamed from "Discriminator" to "$type".
        // Preserve old name for backward compat with existing documents.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change #2: id no longer contains the discriminator (was "Blog|1", now "1").
        // Preserve old "Blog|<key>" format for existing documents.
        modelBuilder.Entity<Blog>().HasDiscriminatorInJsonId();

        // Breaking change #3: Key property is now mapped directly to JSON "id";
        // previously a shadow property was used. Restore old shadow-id behavior.
        modelBuilder.Entity<Blog>().HasShadowId();

        // Breaking change #4: HasIndex() now throws for Cosmos DB — removed.
        // (was: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);)
    }
}

